const body = $input.first().json.body;
const { player1, player2, surface, matchData } = body;
const prompt = `You are a tennis analyst AI. Analyze this match:

Player 1: ${player1?.name || 'Unknown'} (${player1?.country || ''})
  - Play style: ${player1?.play_style || 'Unknown'}
  - Strengths: ${player1?.strengths?.join(', ') || 'Unknown'}
  - Weaknesses: ${player1?.weaknesses?.join(', ') || 'Unknown'}
  - Best surfaces: ${player1?.best_surfaces?.join(', ') || 'Unknown'}
  - Recent matches: ${JSON.stringify(player1?.recent_matches || [])}

Player 2: ${player2?.name || 'Unknown'} (${player2?.country || ''})
  - Play style: ${player2?.play_style || 'Unknown'}
  - Strengths: ${player2?.strengths?.join(', ') || 'Unknown'}
  - Weaknesses: ${player2?.weaknesses?.join(', ') || 'Unknown'}
  - Best surfaces: ${player2?.best_surfaces?.join(', ') || 'Unknown'}
  - Recent matches: ${JSON.stringify(player2?.recent_matches || [])}

Surface: ${surface || 'Unknown'}

Provide:
1. Predicted winner (player name)
2. Confidence (0.0-1.0)
3. Key reasoning (2-3 sentences)
4. Tactics for Player 1
5. Tactics for Player 2

Return as JSON: { predicted_winner, confidence, reasoning, tactics_player1, tactics_player2 }`;
return [{ json: { prompt } }];

const response = $input.first().json;
const content = response.choices?.[0]?.message?.content || '';
try {
  const parsed = JSON.parse(content.match(/\{[\s\S]*\}/)?.[0] || content);
  return [{ json: { success: true, ...parsed } }];
} catch (e) {
  return [{ json: { success: false, error: 'Failed to parse AI response', raw: content } }];
}
